function leftRightGaps(nums: number[]): number[] {
  return nums.map((_, i) => {
    let left = 0, right = 0;
    for (let j = 0; j < i; j++) left += nums[j];
    for (let j = i + 1; j < nums.length; j++) right += nums[j];
    return Math.abs(left - right);
  });
}

