function leftRightGaps(nums: number[]): number[] {
  let total = 0;
  for (const v of nums) total += v;
  const out: number[] = [];
  let left = 0;
  for (const v of nums) {
    const right = total - left - v;
    out.push(Math.abs(left - right));
    left += v;
  }
  return out;
}

